package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for English (G.C.E. O/L).
 * Part 2: Categories 11 to 20 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankEnglishSetsPart2 {

  fun getCard(setNum: Int, cardNum: Int, grade: String): CardContentTuple {
    val c = cardNum.coerceIn(1, 20)
    val isGrade11 = grade.contains("11") || grade == "11"
    return when (setNum) {
      11 -> if (isGrade11) grade11_set11[(c - 1) % grade11_set11.size] else set11[(c - 1) % set11.size]
      12 -> if (isGrade11) grade11_set12[(c - 1) % grade11_set12.size] else set12[(c - 1) % set12.size]
      13 -> if (isGrade11) grade11_set13[(c - 1) % grade11_set13.size] else set13[(c - 1) % set13.size]
      14 -> if (isGrade11) grade11_set14[(c - 1) % grade11_set14.size] else set14[(c - 1) % set14.size]
      15 -> if (isGrade11) grade11_set15[(c - 1) % grade11_set15.size] else set15[(c - 1) % set15.size]
      16 -> if (isGrade11) grade11_set16[(c - 1) % grade11_set16.size] else set16[(c - 1) % set16.size]
      17 -> if (isGrade11) grade11_set17[(c - 1) % grade11_set17.size] else set17[(c - 1) % set17.size]
      18 -> if (isGrade11) grade11_set18[(c - 1) % grade11_set18.size] else set18[(c - 1) % set18.size]
      19 -> if (isGrade11) grade11_set19[(c - 1) % grade11_set19.size] else set19[(c - 1) % set19.size]
      20 -> if (isGrade11) grade11_set20[(c - 1) % grade11_set20.size] else set20[(c - 1) % set20.size]
      else -> set11[(c - 1) % set11.size]
    }
  }

